/**
 * `npm run swarm` — SWARM_SIZE agents paying for the tools they use, in parallel.
 *
 * Each swarm agent has its own owner (generated by `npm run keys`) that signs
 * the agent's public key with a ProtoWallet, so every agent counts as a
 * separate supporter. Agents loop until SWARM_DURATION_SEC is up or they run
 * out of money, waiting SWARM_DELAY_MS between contributions.
 *
 * `npm run swarm:demo` is the same with a 60-second run.
 *
 * Same code in both modes: in dry-run nothing is broadcast; with DRY_RUN=false
 * this spends real satoshis.
 */
import { PrivateKey, ProtoWallet } from '@bsv/sdk'
import { signAgentAttestation } from '@upstream/shared/attestation'
import { loadBudget, sats } from '@upstream/shared/budget'
import { loadKeys } from '@upstream/shared/keystore'
import { describeMode, loadRuntime } from '@upstream/shared/runtime'
import { short } from './lib/contribute.ts'
import { loadSwarmConfig } from './lib/swarm/config.ts'
import { runSwarm, type SwarmAgent } from './lib/swarm/runner.ts'
import { fetchTally, printTally, requireServer } from './lib/swarm/server.ts'
import { stackFor, TOOL_PROFILES } from './lib/swarm/usage.ts'
import { getUtxo } from './lib/utxos.ts'

const runtime = loadRuntime(process.env)
const budget = loadBudget(process.env)
const config = loadSwarmConfig(process.env, process.argv.slice(2))
const verbose = process.argv.includes('--verbose')

async function main(): Promise<void> {
  console.log(describeMode(runtime))
  console.log('')
  await requireServer(runtime)

  const keys = loadKeys()
  const pairs = keys.swarm.slice(0, budget.swarmSize)
  const funded = pairs.filter(p => getUtxo(p.agent.label) !== undefined)
  if (funded.length === 0) {
    console.error('No swarm agent holds a spendable output.')
    console.error(runtime.dryRun ? '  npm run seed-agents' : '  fund the agents in the web app first')
    process.exitCode = 1
    return
  }

  // Sign each agent's key once up front, rather than on every contribution.
  const agents: SwarmAgent[] = await Promise.all(
    funded.map(async p => ({
      label: p.agent.label,
      key: PrivateKey.fromHex(p.agent.privHex),
      attestation: await signAgentAttestation(
        new ProtoWallet(PrivateKey.fromHex(p.owner.privHex)),
        p.agent.pubKey
      )
    }))
  )

  // Show who will support what before anything happens.
  const adopters = new Map<string, number>()
  for (const a of agents) for (const t of stackFor(a.label)) adopters.set(t.projectId, (adopters.get(t.projectId) ?? 0) + 1)

  console.log(
    `Swarm: ${agents.length} agents (${pairs.length - funded.length} unfunded skipped), ` +
      `${config.durationSec}s, ${config.delayMinMs}-${config.delayMaxMs} ms between calls, ` +
      `${sats(budget.contributionSats)} sats per call`
  )
  console.log('Agents whose stack uses each project:')
  for (const p of TOOL_PROFILES) {
    console.log(`  ${p.projectId.padEnd(14)} ${p.tool.padEnd(16)} ${String(adopters.get(p.projectId) ?? 0).padStart(3)} agents`)
  }
  console.log('')

  const controller = new AbortController()
  process.once('SIGINT', () => {
    console.log('\nStopping — letting in-flight contributions finish…')
    controller.abort()
  })

  let lastProgress = Date.now()
  let count = 0
  const stats = await runSwarm({
    agents,
    config,
    budget,
    runtime,
    signal: controller.signal,
    onEvent: e => {
      if (e.kind === 'paid') {
        count++
        if (verbose || !e.result.accepted) {
          console.log(
            `  ${e.agent} → ${e.tool.projectId.padEnd(14)} ${short(e.result.txid)} ` +
              (e.result.accepted ? 'counted' : `REJECTED: ${e.result.serverMessage}`)
          )
        }
        if (Date.now() - lastProgress > 5_000) {
          lastProgress = Date.now()
          console.log(`  … ${count} contributions so far`)
        }
      } else if (e.kind === 'retired') {
        console.log(`  ${e.agent} stopped: ${e.reason}`)
      } else {
        console.log(`  ${e.agent} error: ${e.message}`)
      }
    }
  })

  console.log('')
  console.log(
    `Done in ${(stats.elapsedMs / 1000).toFixed(1)}s: ${stats.txs} transactions ` +
      `(${stats.accepted} counted, ${stats.rejected} rejected), ${sats(stats.fees)} sats in fees, ` +
      `${stats.errors} errors, ${stats.retired} agents stopped early.`
  )
  console.log(`Broadcast: ${runtime.dryRun ? 'NO (dry run)' : `yes, via ${runtime.arcadeUrl}`}`)
  console.log('')
  console.log('  project          txs   supporters      sats')
  for (const p of TOOL_PROFILES) {
    const s = stats.byProject.get(p.projectId)
    console.log(
      `  ${p.projectId.padEnd(14)} ${String(s?.txs ?? 0).padStart(5)} ${String(s?.supporters.size ?? 0).padStart(12)} ${sats(s?.sats ?? 0).padStart(9)}`
    )
  }
  console.log('')

  const tally = await fetchTally(runtime)
  if (tally !== null) printTally(tally)
  if (stats.txs === 0) process.exitCode = 1
}

main().catch((err: unknown) => {
  console.error(`\n${(err as Error).message}`)
  process.exitCode = 1
})
